/**
 * 会话 ID 白名单（issue #103）：session 参数进入任何路径拼接/文件系统寻址前
 * 的统一防御。口径与 team-overview 先例一致——`/^[A-Za-z0-9_-]{1,128}$/`，
 * 白名单外字符（含路径逃逸 `../`、控制字符、超长）一律拒绝。
 *
 * 错误码约定：参数缺失返回既有文案（missing session parameter），格式非法
 * 返回 400 invalid session parameter（对齐 overview 口径）。
 */
export const SESSION_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

export function isValidSessionId(sessionId: string): boolean {
  return SESSION_PATTERN.test(sessionId);
}

src/plugin/team-home.ts.source:
/**
 * 宿主绑定层：TEAM_HOME 解析（ADR 0005/#13 冻结口径）。
 *
 * runtime 纯库只认抽象根；这里把 `<主会话id>` 绑定到
 * `<DSH_HOME>/xiaozhuge/sessions/<主会话id>`，一个主会话 = 一个实例根，
 * 崩溃恢复可借 dsh transcript 回溯。
 *
 * 三级模板来源（ADR 0013）：
 * - user 层 = `<DSH_HOME>/xiaozhuge/templates/`（ADR 0002 定稿落点）
 * - project 层 = `<projectRoot>/.xiaozhuge/templates/`（ADR 0002 定稿落点）
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

/** 解析 DSH_HOME（默认 ~/.dsh）。 */
export function resolveDshHome(): string {
  return process.env.DSH_HOME ?? join(homedir(), ".dsh");
}

/**
 * 解析某主会话的 TEAM_HOME 实例根。
 * @param sessionId 主会话 id（dsh session id）。
 */
export function resolveTeamHome(sessionId: string): string {
  return join(resolveDshHome(), "xiaozhuge", "sessions", sessionId);
}

/** 视图解析结果：teamHome 为供数实例根；membership 非空 = 子会话反查命中。 */
export interface TeamHomeResolution {
  teamHome: string;
  /** 命名随 HTTP 响应体 snake_case 口径（is_team/playbook_digest 同风格）。 */
  membership: { root_session: string; member: string } | null;
}

/**
 * 视图供数解析（#97 问题 3）：先按主会话直查；未命中实例根时，按成员
 * durable id 反查所属实例（扫各实例 agents.json，纯读）。子会话页据此
 * 以实例根身份取数，打通「子会话 → 所属团队」反向入口。
 *
 * 边界：扫描范围限本 DSH_HOME 的 xiaozhuge/sessions；单实例注册表损坏
 * 跳过继续（不整体失败）；实例未初始化（team.yaml 不在）视为未命中，
 * 与 team/status 判定一致。
 */
export function resolveTeamHomeForView(sessionId: string): TeamHomeResolution {
  const direct = resolveTeamHome(sessionId);
  if (existsSync(join(direct, "team.yaml"))) {
    return { teamHome: direct, membership: null };
  }
  const sessionsDir = join(resolveDshHome(), "xiaozhuge", "sessions");
  let entries: string[] = [];
  try {
    // 显式排序：命中顺序确定化（durable id 全局唯一时理论上无多实例冲突，
    // 排序保证极端情况下行为可复现）。
    entries = readdirSync(sessionsDir).sort();
  } catch {
    return { teamHome: direct, membership: null };
  }
  for (const entry of entries) {
    const teamHome = join(sessionsDir, entry);
    const agentsJson = join(teamHome, "agents.json");
    if (!existsSync(agentsJson) || !existsSync(join(teamHome, "team.yaml"))) continue;
    try {
      const reg = JSON.parse(readFileSync(agentsJson, "utf8")) as {
        members?: Record<string, { durableId?: string; member?: string }>;
      };
      for (const m of Object.values(reg.members ?? {})) {
        if (m.durableId === sessionId && typeof m.member === "string") {
          return { teamHome, membership: { root_session: entry, member: m.member } };
        }
      }
    } catch {
      // 注册表损坏：跳过该实例继续扫描
    }
  }
  return { teamHome: direct, membership: null };
}

/** user 层模板根（ADR 0013）：<DSH_HOME>/xiaozhuge/templates/。 */
export function userTemplatesRoot(): string {
  return join(resolveDshHome(), "xiaozhuge", "templates");
}

/** project 层模板根（ADR 0013）：<projectRoot>/.xiaozhuge/templates/。 */
export function projectTemplatesRoot(projectRoot: string): string {
  return join(projectRoot, ".xiaozhuge", "templates");
}

src/plugin/team-launch.ts.source:
/**
 * Team 拉起入口 HTTP 面（#51，ADR 0011；#51 修订：入口收敛进会话内）。
 *
 * 一键链路（浏览器端 client 插件在输入框内完成，不再打开独立页）：
 *   ① session.list 推导当前会话（blank 首轮判定 + cwd 工作区推导）
 *   → ② POST /api/xiaozhuge/team/create（本文件：服务端跑 init 持久化）
 *   → ③ POST /api/session.prompt 投递 tier0_prompt 首条消息
 *     （输入框草稿作为首条用户任务，空则只投递规程）。
 *
 * init 由此从 LLM 工具面移到 HTTP 面：team_init 工具下线，handler 逻辑
 * 保留复用。安全语义沿 Gate Console 先例：POST 同源 Origin + Fetch
 * Metadata 双头断言；scenario 运行时校验 builtin 白名单。
 *
 * 输入框内「创建团队」按钮与场景浮层由客户端插件（src/client/）经
 * conversation.input.right 官方插槽渲染（ADR 0014）。
 */
import { existsSync, readFileSync } from "node:fs";
import type { IncomingMessage, ServerResponse } from "node:http";
import { join } from "node:path";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { resolveTeamHome, resolveTeamHomeForView, userTemplatesRoot, projectTemplatesRoot } from "./team-home.js";
import { createHandlers, PACKAGE_ROOT } from "./handlers.js";
import { layout, listScenarios } from "../runtime/index.js";
import { fetchSiteAllowed, originAllowed } from "./gate-console.js";
import { isValidSessionId } from "./session-id.js";

/** 独立入口页路径（保留为兜底；client 插件不再跳转此页）。 */
export const ROUTES_LAUNCH = "/xiaozhuge/launch";

function writeJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<string> {
  let raw = "";
  for await (const chunk of req) raw += String(chunk);
  return raw;
}

/** 启动消息头（不含规程正文）；bootMessage 与页面脚本共用同一前缀。
 * 尾部附首 turn 检查单（#79 L2）：注意力聚焦三件事，规程正文不再依赖跳读。 */
export const BOOT_MESSAGE_HEAD =
  "团队已由人经入口创建，实例初始化完成。以下是你的 Tier-0 规程与场景编排" +
  "提示词全文（规程在前、场景段在后，以固定分隔符分界），请从启动对账节开始执行。" +
  "首 turn 检查单：① 第一个工具调用必须是 team_reconcile（readiness gate，失败即上行摘要）；② 确认 goal 已创建；③ 输出首轮摘要上行。";

/** 启动消息 = 前缀 + 组装好的 tier0_prompt。 */
export function bootMessage(tier0Prompt: string): string {
  return `${BOOT_MESSAGE_HEAD}\n\n${tier0Prompt}`;
}

/** Team 拉起入口路由组（scenarios/status/create API + 独立入口页）。 */
export function makeLaunchRoutes(): WebRoute[] {
  return [
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/scenarios",
      handler: async (req, res) => {
        const url = new URL(req.url ?? "/", "http://localhost");
        const workspace = url.searchParams.get("workspace") || undefined;
        // 三级来源根组装（project 层可选，需 workspace 参数）
        const roots: Array<{ source: "builtin" | "user" | "project"; dir: string }> = [
          { source: "builtin", dir: join(PACKAGE_ROOT, "templates") },
          { source: "user", dir: userTemplatesRoot() },
        ];
        if (workspace) {
          roots.push({ source: "project", dir: projectTemplatesRoot(workspace) });
        }
        writeJson(res, 200, { scenarios: listScenarios(roots) });
      },
    },
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/status",
      handler: async (req, res) => {
        const url = new URL(req.url ?? "/", "http://localhost");
        const sessionId = url.searchParams.get("session");
        if (!sessionId) {
          writeJson(res, 400, { error: "missing session parameter" });
          return;
        }
        // 白名单防御（issue #103）：sessionId 进入文件系统寻址前校验，
        // 错误码对齐 overview 口径。
        if (!isValidSessionId(sessionId)) {
          writeJson(res, 400, { error: "invalid session parameter" });
          return;
        }
        // 视图供数解析：主会话直查优先；子会话按成员 durable id 反查所属
        // 实例（#97 问题 3），命中即以实例根身份应答并附归属信息。
        const view = resolveTeamHomeForView(sessionId);
        const l = layout(view.teamHome);
        // 团队会话判定：实例根已初始化（team.yaml 快照在场）。
        if (!existsSync(l.teamYaml)) {
          writeJson(res, 200, { is_team: false });
          return;
        }
        try {
          const snap = JSON.parse(readFileSync(l.teamYaml, "utf8")) as {
            name?: string;
            playbook_digest?: string;
          };
          writeJson(res, 200, {
            is_team: true,
            name: snap.name ?? null,
            playbook_digest: snap.playbook_digest ?? null,
            ...(view.membership !== null ? { membership: view.membership } : {}),
          });
        } catch {
          writeJson(res, 200, {
            is_team: true,
            name: null,
            playbook_digest: null,
            ...(view.membership !== null ? { membership: view.membership } : {}),
          });
        }
      },
    },
    {
      kind: "exact",
      path: "/api/xiaozhuge/team/create",
      handler: async (req, res) => {
        if (req.method !== "POST") {
          writeJson(res, 405, { error: "method not allowed" });
          return;
        }
        // 安全最小集：与 Gate Console 同款双头断言（复用同一实现）。
        if (!originAllowed(req)) {
          writeJson(res, 403, { error: "forbidden: missing or cross-origin Origin header" });
          return;
        }
        if (!fetchSiteAllowed(req)) {
          writeJson(res, 403, { error: "forbidden: cross-site Sec-Fetch-Site" });
          return;
        }
        try {
          const body = JSON.parse(await readBody(req)) as {
            session?: string;
            scenario?: string;
            source?: string;
            workspace?: string;
            instance_note?: string;
          };
          if (typeof body.session !== "string" || body.session.length === 0) {
            writeJson(res, 400, { error: "session required" });
            return;
          }
          // handler 层负责 scenario 校验（unknown-scenario / ambiguous-scenario 稳定错误码）。
          const handlers = createHandlers(resolveTeamHome(body.session), body.session);
          const value = (await handlers.init({
            scenario: body.scenario,
            source: body.source,
            project_root: body.workspace,
            instance_note: body.instance_note,
          })) as Record<string, unknown>;
          writeJson(res, 200, value);
        } catch (error) {
          const e = error as { code?: string; message?: string };
          const status = e.code === "unknown-scenario" || e.code === "ambiguous-scenario" ? 400 : 409;
          writeJson(res, status, {
            error: { code: e.code ?? "internal-error", message: e.message ?? String(error) },
          });
        }
      },
    },
    {
      kind: "exact",
      path: ROUTES_LAUNCH,
      handler: async (_req, res) => {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
        res.end(launchPageHtml());
      },
    },
  ];
}

/** 独立入口页（内联 HTML；一键编排 workspace→session→init→prompt 四步）。 */
export function launchPageHtml(): string {
  const headLiteral = JSON.stringify(BOOT_MESSAGE_HEAD);
  return `<!doctype html>
<html lang="zh">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>小诸葛 · 创建团队</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; background: #f6f7f9; color: #1a1a1a; }
  @media (prefers-color-scheme: dark) { body { background: #14161a; color: #e8e8ea; } .card { background: #1e2128 !important; border-color: #33383f !important; } }
  h1 { font-size: 18px; margin: 8px 0 12px; }
  .card { border: 1px solid #ddd; border-radius: 10px; padding: 14px; background: #fff; max-width: 640px; margin-bottom: 12px; }
  label { display: block; font-size: 13px; margin: 10px 0 4px; }
  input, select { width: 100%; box-sizing: border-box; padding: 7px 9px; border: 1px solid #bbb; border-radius: 6px; background: inherit; color: inherit; font-size: 14px; }
  button { padding: 8px 18px; border-radius: 6px; border: none; cursor: pointer; font-size: 14px; background: #2da44e; color: #fff; margin-top: 12px; }
  button:disabled { opacity: .5; cursor: wait; }
  .hint { font-size: 12px; opacity: .65; margin-top: 6px; white-space: pre-wrap; }
  .err { color: #cf222e; font-size: 13px; margin-top: 8px; white-space: pre-wrap; }
</style>
</head>
<body>
<h1>创建团队</h1>
<div class="card">
  <label>工作区路径（宿主 workspace，绝对路径）</label>
  <input id="ws-path" placeholder="/path/to/workspace">
  <label>场景模板</label>
  <select id="scenario"></select>
  <label>备注（可选）</label>
  <input id="note" placeholder="instance note">
  <button id="go">一键建团并投递规程</button>
  <div class="err" id="err"></div>
  <div class="hint" id="log"></div>
</div>
<script>
const $ = (s) => document.querySelector(s);
const BOOT_HEAD = ${headLiteral};
const log = (m) => ($("#log").textContent += m + "\\n");
async function jfetch(method, path, body) {
  const r = await fetch(path, {
    method,
    headers: body !== undefined ? { "content-type": "application/json" } : {},
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok && data.error) {
    throw new Error(typeof data.error === "object"
      ? (data.error.code + ": " + data.error.message)
      : String(data.error));
  }
  if (!r.ok) throw new Error("HTTP " + r.status);
  return data;
}
(async () => {
  const sel = $("#scenario");
  const list = (await jfetch("GET", "/api/xiaozhuge/team/scenarios")).scenarios;
  for (const s of list) {
    const o = document.createElement("option");
    o.value = s.name + "|" + s.source;
    o.textContent = s.name + " (" + s.source + ")";
    sel.appendChild(o);
  }
})();
$("#go").addEventListener("click", async () => {
  const btn = $("#go");
  btn.disabled = true;
  $("#err").textContent = "";
  $("#log").textContent = "";
  try {
    const wsPath = $("#ws-path").value.trim();
    if (!wsPath) throw new Error("请填写工作区路径");
    const ws = await jfetch("POST", "/api/workspace.create", { path: wsPath });
    log("workspace: " + ws.workspace.workspaceId);
    const sess = await jfetch("POST", "/api/session.create", {
      workspaceId: ws.workspace.workspaceId,
      agentPreset: "standard",
    });
    const sessionId = sess.sessionId;
    log("session: " + sessionId);
    const selVal = $("#scenario").value;
    const pipe = selVal.indexOf("|");
    const scenario = pipe >= 0 ? selVal.slice(0, pipe) : selVal;
    const source = pipe >= 0 ? selVal.slice(pipe + 1) : undefined;
    const created = await jfetch("POST", "/api/xiaozhuge/team/create", {
      session: sessionId,
      scenario: scenario,
      source: source,
      workspace: wsPath,
      instance_note: $("#note").value.trim() || null,
    });
    log("team initialized: " + created.home);
    await jfetch("POST", "/api/session.prompt", {
      sessionId,
      mode: "queue",
      content: [{ type: "text", text: BOOT_HEAD + "\\n\\n" + created.tier0_prompt }],
    });
    log("规程已投递。打开会话 " + sessionId + " 即可开始。");
  } catch (e) {
    $("#err").textContent = String(e.message ?? e);
  } finally {
    btn.disabled = false;
  }
});
</script>
</body>
</html>`;
}

src/plugin/team-overview.ts.source:
/**
 * 团队视图总览 HTTP 面（issue #68）：GET /api/xiaozhuge/team/overview?session=。
 *
 * 只读投影零写路径：agents.json + 各房间 events.jsonl 尾部窗口 + 各房间
 * state 目录黑板分片 → runtime 纯函数归约（src/runtime/view/overview.ts）→ JSON。
 * 复用 team/status 的 GET 先例（无 POST，不涉同源双头断言）。
 *
 * 尾部窗口语义（issue「归约 events.jsonl 尾部」）：文件超过 TAIL_WINDOW_BYTES
 * 时仅读末尾窗口字节，窗口起点落在行中间则丢弃首个残行——append-only 流的
 * 尾部即最新状态，头部历史对监控视图无增量价值；坏行跳过与 EventLog 写入侧
 * torn-tail 语义一致。
 *
 * 轮询减负三件套（对抗性评审阻塞项）：stat 快路径（输入文件 mtime+size 未变
 * 直接回缓存投影）、per-TEAM_HOME single-flight（并发轮询合并为一次解析）、
 * ETag/304（内容指纹未变空响应体）。前端 5s×N 窗口的绝大多数周期落在此处，
 * 不产生解析成本。
 */
import { existsSync, readdirSync, statSync } from "node:fs";
import { readFile } from "node:fs/promises";
import type { IncomingMessage, ServerResponse } from "node:http";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { join } from "node:path";
import type { EventRecord, TeamOverview } from "../runtime/index.js";
import { layout, listShards, reduceOverview, Registry } from "../runtime/index.js";
import { SESSION_PATTERN } from "./session-id.js";

/** 路由路径。 */
export const ROUTES_OVERVIEW = "/api/xiaozhuge/team/overview";

/** 事件尾部读取窗口上限（字节）。 */
export const TAIL_WINDOW_BYTES = 256 * 1024;
/** 投影进视图模型的尾部事件条数上限。 */
export const TAIL_EVENT_LIMIT = 50;

// session 参数白名单统一取自 session-id.ts（issue #103），本文件不再私有定义。

function writeJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

/** 读 jsonl 尾部窗口并解析为事件记录（残行丢弃，坏行跳过）。 */
export async function readEventsTail(
  file: string,
  maxBytes = TAIL_WINDOW_BYTES,
): Promise<EventRecord[]> {
  if (!existsSync(file)) return [];
  const size = statSync(file).size;
  if (size === 0) return [];
  const start = size > maxBytes ? size - maxBytes : 0;
  const buf = await readFile(file);
  let raw = start > 0 ? buf.subarray(start).toString("utf8") : buf.toString("utf8");
  const lines = raw.split("\n");
  // 从窗口中段起读时首行大概率残缺：丢弃。
  if (start > 0 && lines.length > 0) lines.shift();
  const events: EventRecord[] = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      events.push(JSON.parse(trimmed) as EventRecord);
    } catch {
      // torn tail / 坏行：跳过（只读面不做修复）。
    }
  }
  return events.slice(-TAIL_EVENT_LIMIT);
}

/** 组装归约输入并投影（IO 与纯函数的分界）。 */
export async function buildOverview(teamHome: string): Promise<TeamOverview> {
  const l = layout(teamHome);
  const registry = await new Registry(teamHome).read();
  const roomNames = existsSync(l.roomsDir)
    ? readdirSync(l.roomsDir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort()
    : [];
  const rooms = [];
  for (const room of roomNames) {
    const dir = join(l.roomsDir, room);
    rooms.push({
      room,
      events: await readEventsTail(join(dir, "events.jsonl")),
      shards: await listShards(teamHome, room),
    });
  }
  return reduceOverview({ registry, rooms });
}

/* ---------------- 投影缓存：stat 指纹 + single-flight + ETag ---------------- */

interface CacheEntry {
  /** 内容指纹（agents.json + 各房间 events.jsonl 的 mtimeMs:size 串列哈希）。 */
  etag: string;
  body: TeamOverview;
}

/** per-TEAM_HOME 投影缓存（有界：超出上限清最旧，防长驻进程缓慢累积）。 */
const overviewCache = new Map<string, CacheEntry>();
const CACHE_LIMIT = 128;
/** per-TEAM_HOME in-flight 归约（single-flight）。 */
const inflight = new Map<string, Promise<CacheEntry>>();

function fileStamp(path: string): string {
  if (!existsSync(path)) return "-";
  const s = statSync(path);
  return `${s.mtimeMs.toFixed(3)}:${s.size}`;
}

/** 输入文件集指纹：任一事件流/注册表变化即翻转。 */
function fingerprint(teamHome: string): string {
  const l = layout(teamHome);
  const parts = [fileStamp(l.agentsJson)];
  if (existsSync(l.roomsDir)) {
    for (const entry of readdirSync(l.roomsDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      parts.push(`${entry.name}=${fileStamp(join(l.roomsDir, entry.name, "events.jsonl"))}`);
    }
  }
  return parts.join("|");
}

async function reduceCached(teamHome: string): Promise<CacheEntry> {
  const fp = fingerprint(teamHome);
  const cached = overviewCache.get(teamHome);
  if (cached !== undefined && cached.etag === fp) return cached;
  const body = await buildOverview(teamHome);
  const fresh: CacheEntry = { etag: fp, body };
  if (overviewCache.size >= CACHE_LIMIT) {
    const oldest = overviewCache.keys().next().value;
    if (oldest !== undefined) overviewCache.delete(oldest);
  }
  overviewCache.set(teamHome, fresh);
  return fresh;
}

/** single-flight 包装：并发轮询合并为一次归约解析。 */
function reduceOnce(teamHome: string): Promise<CacheEntry> {
  const running = inflight.get(teamHome);
  if (running !== undefined) return running;
  const p = reduceCached(teamHome).finally(() => inflight.delete(teamHome));
  inflight.set(teamHome, p);
  return p;
}

/** 团队总览只读路由。 */
export function makeOverviewRoute(teamHomeFor: (sessionId: string) => string): WebRoute {
  return {
    kind: "exact",
    path: ROUTES_OVERVIEW,
    handler: async (req: IncomingMessage, res: ServerResponse) => {
      if (req.method !== "GET") {
        writeJson(res, 405, { error: "method not allowed" });
        return;
      }
      const url = new URL(req.url ?? "/", "http://localhost");
      const sessionId = url.searchParams.get("session");
      if (!sessionId || !SESSION_PATTERN.test(sessionId)) {
        writeJson(res, 400, { error: "invalid session parameter" });
        return;
      }
      const teamHome = teamHomeFor(sessionId);
      // 非团队会话短路：实例根未初始化（team.yaml 快照不在场），与 team/status 判定一致。
      if (!existsSync(layout(teamHome).teamYaml)) {
        writeJson(res, 200, { isTeam: false, masterRegistered: false, members: [], rooms: [] });
        return;
      }
      try {
        const { etag, body } = await reduceOnce(teamHome);
        const clientEtag = req.headers["if-none-match"];
        if (clientEtag === etag) {
          res.writeHead(304, { etag });
          res.end();
          return;
        }
        res.writeHead(200, { "content-type": "application/json; charset=utf-8", etag });
        res.end(JSON.stringify(body));
      } catch (error) {
        writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) });
      }
    },
  };
}

src/plugin/tool-manifest.ts.source:
/**
 * 框架工具面自述（ADR 0015 决策 3，#66）。
 *
 * 建团首条消息尾部追加的「保留段」：仅自述本插件注册的 team_* 工具面，
 * 附显式盲区声明。定位是概率缓解——消除「凭记忆推断工具不存在」的信息缺位
 * 前提；不声称覆盖宿主侧全量工具面（goal/subagent/MCP 不在自述范围），
 * 否则会制造新的权威幻觉（模型反推「清单上没有 = 不存在」）。
 *
 * 本模块是清单的单一事实源：host.ts 的注册名单与本清单经契约测试互锁
 * （tests/plugin/tool-manifest.test.ts），防漂移。
 */

/** 保留段定界符（framework-generated 水印内置；改动 = 协议变更，走增量 ADR）。 */
export const TOOL_MANIFEST_SEPARATOR =
  "\n\n===== framework tool manifest (framework-generated; informational only) =====\n\n";

/** 本插件注册的 team_* 工具自述（名称 → 一句话用途；与 host.ts 注册面一致）。 */
export const TEAM_TOOL_MANIFEST: ReadonlyArray<readonly [string, string]> = [
  ["team_spawn", "登记成员 durable id 入注册表"],
  ["team_dispatch", "注册 → 指派 → 派单复合原语（半事务，失败报告已完成步骤）"],
  ["team_send", "定向信箱投递"],
  ["team_inbox", "读未读 / 认领指定信封"],
  ["team_ack", "确认信封处理完成"],
  ["team_task_create", "任务账本建账（mutex 预检）"],
  ["team_task_update", "任务状态机流转 / 改派"],
  ["team_task_list", "任务账本查询"],
  ["team_state_get", "黑板读"],
  ["team_state_set", "黑板写（running|blocked|done）"],
  ["team_reconcile", "对账全量视图（scope=audit 为旁路 report-only）"],
  ["team_handoff", "显式交接（dod 回执核验）"],
];

/** 生成完整保留段文本（不含前导分隔符，调用方拼接）。 */
export function toolManifestText(): string {
  const lines: string[] = [
    "以下工具面清单由框架生成，仅供导航：工具可用性一律以当轮运行时实际注册为准，",
    "本清单不是授权依据，也不得据「清单未列」推断某工具不存在。",
    "",
    "本框架注册的 team_* 工具：",
    ...TEAM_TOOL_MANIFEST.map(([name, desc]) => `- ${name}：${desc}`),
    "",
    "盲区声明：goal 管理、subagent 启动/唤醒、MCP 等宿主侧能力不在本清单范围内，",
    "其存在性请以当轮系统提示词与实际可用工具为准。",
    "启动对账一律先跑 team_reconcile：一次返回成员对照表、任务快照与事件游标。",
  ];
  return lines.join("\n");
}

/** tier0_prompt 组装后追加保留段（幂等：重复追加拒绝，防双份清单漂移）。 */
export function appendToolManifest(tier0Prompt: string): string {
  if (tier0Prompt.includes(TOOL_MANIFEST_SEPARATOR)) {
    throw new Error("double-append: tool manifest section already present");
  }
  return `${tier0Prompt}${TOOL_MANIFEST_SEPARATOR}${toolManifestText()}`;
}

src/plugin/workspace-audit.ts.source:
/**
 * 工作区旁路对账（report-only，ADR 0015 决策 1 · scope=audit 子命令）。
 *
 * 机械比对「账本 touched_paths 登记集合 ↔ 工作树实际新增文件」，
 * 定位是提高违规检出率（威慑），不是杜绝违规——done 迁移卡点待
 * report-only 版跑出真实误报率数据后单独立项评审。
 *
 * 安全硬约束（ADR 0015）：只输出路径 + mtime + size，禁止读取文件内容；
 * 敏感文件名打掩码（防止 .env/密钥类未登记文件的内容线索进入 LLM 上下文）；
 * 扫描根钉死为快照持久化的工作区，不接受调用方传参（防任意目录枚举）；
 * 目录遍历带固定忽略清单与条目上限（防巨树拖垮工具调用）。
 */
import { readdirSync, statSync, existsSync } from "node:fs";
import { join, relative, sep } from "node:path";

/** 单文件审计条目：只有元数据，绝无内容。 */
export interface FileAuditEntry {
  path: string;
  size: number;
  mtime: number;
  /** 敏感文件名命中：路径已掩码，仅保留目录结构与标记。 */
  sensitive_masked: boolean;
}

export interface WorkspaceAuditReport {
  available: boolean;
  reason?: string;
  scanned_root?: string;
  /** 工作树中存在、但未登记于任何任务 touched_paths 的文件。 */
  unregistered_files: FileAuditEntry[];
  /** 账本登记了、但工作树中不存在的路径（过期登记）。 */
  stale_registered_paths: string[];
  truncated: boolean;
}

/** 固定忽略目录（构建产物 / 依赖 / 版本控制 / 框架运行时）。 */
const IGNORED_DIRS = new Set([
  ".git",
  "node_modules",
  "dist",
  "coverage",
  "reports",
  ".stryker-tmp",
  ".dsh",
  ".xiaozhuge",
]);

/** 敏感文件名模式（命中即掩码，绝不展开内容或完整路径）。 */
const SENSITIVE_NAME_PATTERNS = [
  /^\.env/i,
  /\.pem$/i,
  /id_rsa/i,
  /id_ed25519/i,
  /(^|[._-])credential/i,
  /(^|[._-])secret/i,
  /(^|[._-])token/i,
  /(^|[._-])password/i,
];

/** 条目上限：超过即截断并置 truncated（防巨树）。 */
const MAX_ENTRIES = 5000;
/** 单目录扇出上限：防御符号链接循环之外的异常深树。 */
const MAX_DEPTH = 24;

function isSensitiveName(name: string): boolean {
  return SENSITIVE_NAME_PATTERNS.some((re) => re.test(name));
}

function maskSensitive(entry: FileAuditEntry): FileAuditEntry {
  const parts = entry.path.split(sep);
  parts[parts.length - 1] = "<masked:sensitive-name>";
  return { ...entry, path: parts.join(sep), sensitive_masked: true };
}

function walk(root: string, rel: string, depth: number, out: FileAuditEntry[], state: { truncated: boolean }): void {
  if (state.truncated || out.length >= MAX_ENTRIES || depth > MAX_DEPTH) {
    if (out.length >= MAX_ENTRIES) state.truncated = true;
    return;
  }
  let entries: string[];
  try {
    entries = readdirSync(join(root, rel));
  } catch {
    return; // 无权限/已消失：跳过，不中断对账
  }
  for (const name of entries) {
    if (out.length >= MAX_ENTRIES) {
      state.truncated = true;
      return;
    }
    const relChild = rel ? `${rel}${sep}${name}` : name;
    const abs = join(root, relChild);
    let st;
    try {
      st = statSync(abs);
    } catch {
      continue;
    }
    if (st.isDirectory()) {
      if (!IGNORED_DIRS.has(name)) walk(root, relChild, depth + 1, out, state);
    } else if (st.isFile()) {
      const entry: FileAuditEntry = {
        path: relChild,
        size: st.size,
        mtime: st.mtimeMs,
        sensitive_masked: false,
      };
      out.push(isSensitiveName(name) ? maskSensitive(entry) : entry);
    }
  }
}

/**
 * 对账报告：工作树全量文件（元数据）与账本登记集合的双向 diff。
 * @param workspace 审计根（必须来自快照持久化字段；null 即审计不可用）。
 * @param registeredPaths 账本全部任务的 touched_paths 并集。
 */
export function auditWorkspace(workspace: string | null, registeredPaths: string[]): WorkspaceAuditReport {
  if (!workspace || !existsSync(workspace)) {
    return {
      available: false,
      reason: "workspace not recorded in instance snapshot or missing on disk; audit unavailable",
      unregistered_files: [],
      stale_registered_paths: [],
      truncated: false,
    };
  }
  const files: FileAuditEntry[] = [];
  const state = { truncated: false };
  walk(workspace, "", 0, files, state);

  // 登记 paths 统一归一化为「相对审计根」形态再比对（兼容绝对/相对登记）。
  const normalizedRegistered = new Set<string>();
  for (const p of registeredPaths) {
    const rel = p.startsWith(workspace) ? relative(workspace, p) : p;
    normalizedRegistered.add(rel.split("/").join(sep));
  }

  const unregistered_files = files.filter((f) => !normalizedRegistered.has(f.path));
  const stale_registered_paths = [...normalizedRegistered].filter(
    (p) => !existsSync(join(workspace, p)),
  );

  return {
    available: true,
    scanned_root: workspace,
    unregistered_files,
    stale_registered_paths,
    truncated: state.truncated,
  };
}

tests/plugin/dispatch.test.ts.source:
/**
 * team_dispatch 复合派发原语单测（ADR 0015，#67）。
 * 覆盖：正常三步链路（含 role_inline / provider / model 透传）、
 * 半事务失败（步骤留痕 + 副作用边界）、前置校验、role_inline 白名单、幂等重入。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { layout } from "../../src/runtime/kernel/paths.js";
import { readUnread } from "../../src/runtime/collab/mailbox.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-dispatch-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-dispatch-"));
  handlers = createHandlers(home, SESSION);
});

async function readEvents(): Promise<Array<{ type: string; actor: string; payload?: unknown }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, actor: e.actor, payload: e.payload }));
}

async function createTask(title = "实现 X"): Promise<string> {
  const created = (await handlers.taskCreate({ title, room: "root" })) as {
    ok: true;
    task_id: string;
  };
  return created.task_id;
}

describe("team_dispatch 正常链路", () => {
  it("spawn→assign→send 三步全成，注册表/账本/信箱/事件流逐项核对", async () => {
    await handlers.init({});
    const taskId = await createTask();

    const result = (await handlers.dispatch({
      member: "coder",
      durable_id: "dur-coder",
      role: "coder",
      tier: 1,
      task_id: taskId,
      provider: "deepseek",
      model: "strong-model",
      role_inline: {
        briefing: "专注构建门禁",
        dod: ["build 绿"],
        max_hops: 3,
        as_judge: false,
      },
    })) as {
      ok: boolean;
      member: string;
      durable_id: string;
      task_id: string;
      envelope_id: string;
      steps: string[];
    };

    expect(result.ok).toBe(true);
    expect(result.member).toBe("coder");
    expect(result.durable_id).toBe("dur-coder");
    expect(result.task_id).toBe(taskId);
    expect(result.steps).toEqual(["spawn", "assign", "send"]);

    // 注册表：成员已登记。
    const member = await new Registry(home).getMember("coder");
    expect(member).toMatchObject({ member: "coder", durableId: "dur-coder", tier: 1, status: "spawned" });

    // 账本：任务已指派。
    const ledgerView = (await handlers.taskList({})) as {
      tasks: Array<{ id: string; assignee?: string }>;
    };
    expect(ledgerView.tasks.find((t) => t.id === taskId)?.assignee).toBe("coder");

    // 信箱：派单信封携带任务与 inline 定义、模型档位、框架进度契约。
    const unread = await readUnread(home, "coder");
    expect(unread).toHaveLength(1);
    expect(unread[0]).toMatchObject({
      from: "root",
      to: "coder",
      type: "task-assign",
      body: {
        task_id: taskId,
        title: "实现 X",
        room: "root",
        dod: [],
        role_inline: { briefing: "专注构建门禁", dod: ["build 绿"], max_hops: 3, as_judge: false },
        provider: "deepseek",
        model: "strong-model",
      },
    });
    // 进度契约：固定段在场且带 framework-generated 水印（#86 序 3）。
    const contract = (unread[0]?.body as { progress_contract?: string }).progress_contract ?? "";
    expect(contract).toContain("===== progress contract (framework-generated; informational only) =====");
    expect(contract).toContain("task-done");
    expect(unread[0]?.envelope_id ?? unread[0]!.id).toBe(result.envelope_id);

    // 事件流：三步各留一笔；派单计账携带 task_id（对账机械可得）。
    const events = await readEvents();
    expect(events).toMatchObject([
      { type: "team/init", actor: "system" },
      { type: "task/create", actor: "system" },
      { type: "team/spawn", actor: "system" },
      { type: "task/update", actor: "coder" },
      { type: "mailbox/deliver", actor: "root" },
    ]);
    expect(events.find((e) => e.type === "mailbox/deliver")).toMatchObject({
      payload: { task_id: taskId, msg_type: "task-assign" },
    });
  });

  it("幂等重入：同参数重跑成功，upsert 幂等、派单为新信封（at-least-once）", async () => {
    await handlers.init({});
    const taskId = await createTask();
    const first = await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
      tier: 1,
      task_id: taskId,
    });
    expect(first).toMatchObject({ ok: true, steps: ["spawn", "assign", "send"] });

    // 重入：upsert 幂等、assignee 不变、派单为新信封（at-least-once 语义）。
    const second = (await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
      tier: 1,
      task_id: taskId,
    })) as { ok: boolean; envelope_id: string };
    expect(second.ok).toBe(true);
    expect(second.envelope_id).not.toBe((first as { envelope_id: string }).envelope_id);
    const unread = await readUnread(home, "qa");
    expect(unread).toHaveLength(2);
  });
});

describe("team_dispatch 半事务语义", () => {
  it("step2 rev 冲突即停：已完成 spawn 随错误留痕，assignee 未变、无信封", async () => {
    await handlers.init({});
    const taskId = await createTask();
    // 推高账本 rev，使 dispatch 的 expect_rev 过期。
    await handlers.taskUpdate({ task_id: taskId, rounds: 1 });

    await expect(
      handlers.dispatch({
        member: "coder",
        durable_id: "dur-coder",
        role: "coder",
        tier: 1,
        task_id: taskId,
        expect_rev: 1,
      }),
    ).rejects.toMatchObject({ code: "rev-conflict" });

    // step1 的副作用留存（注册表 + 事件），step2/3 未发生。
    const member = await new Registry(home).getMember("coder");
    expect(member?.member).toBe("coder");
    const events = await readEvents();
    expect(events.filter((e) => e.type === "team/spawn")).toHaveLength(1);
    expect(events.some((e) => e.type === "mailbox/deliver")).toBe(false);
    expect(await readUnread(home, "coder")).toHaveLength(0);

    const ledgerView = (await handlers.taskList({})) as {
      tasks: Array<{ id: string; assignee?: string }>;
    };
    expect(ledgerView.tasks.find((t) => t.id === taskId)?.assignee).toBeUndefined();
  });
});

describe("team_dispatch 前置校验（无副作用）", () => {
  it("任务不存在 → task-not-found，不产生任何落账副作用", async () => {
    await handlers.init({});
    await expect(
      handlers.dispatch({
        member: "coder",
        durable_id: "dur-coder",
        role: "coder",
        tier: 1,
        task_id: "task-absent",
      }),
    ).rejects.toMatchObject({ code: "task-not-found" });
    expect(await new Registry(home).getMember("coder")).toBeUndefined();
    expect(await readUnread(home, "coder")).toHaveLength(0);
    const events = await readEvents();
    expect(events.some((e) => e.type === "team/spawn")).toBe(false);
  });

  it("缺参逐项拒绝（tier 必填数字）", async () => {
    await handlers.init({});
    const taskId = await createTask();
    await expect(
      handlers.dispatch({ member: "c", durable_id: "d", role: "r", task_id: taskId }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
    await expect(
      handlers.dispatch({ member: "c", durable_id: "d", tier: 1, task_id: taskId }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
  });
});

describe("team_dispatch role_inline 校验", () => {
  it("未知字段拒绝", async () => {
    await handlers.init({});
    const taskId = await createTask();
    await expect(
      handlers.dispatch({
        member: "c",
        durable_id: "d",
        role: "r",
        tier: 1,
        task_id: taskId,
        role_inline: { nickname: "x" } as Record<string, unknown>,
      }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
  });

  it("字段类型不符拒绝", async () => {
    await handlers.init({});
    const taskId = await createTask();
    await expect(
      handlers.dispatch({
        member: "c",
        durable_id: "d",
        role: "r",
        tier: 1,
        task_id: taskId,
        role_inline: { as_judge: "yes" },
      }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
    await expect(
      handlers.dispatch({
        member: "c",
        durable_id: "d",
        role: "r",
        tier: 1,
        task_id: taskId,
        role_inline: { dod: [42] },
      }),
    ).rejects.toMatchObject({ code: "invalid-arguments" });
